// Failures from reaching a virtual drive's upstream provider. Raised both by the connectivity probe
// on drive create/update and by the revision read path, which map the same provider failure to the
// same value.
type VirtualDriveUpstreamError int32

const (
	VirtualDriveUpstreamError_VIRTUAL_DRIVE_UPSTREAM_ERROR_UNSPECIFIED VirtualDriveUpstreamError = 0
	// The referenced credentials secret does not exist (deleted or never populated). Admin fix: create/point
	// the drive at a valid secret. Distinct from the invalid/rejected cases below so the admin isn't misdirected.
	VirtualDriveUpstreamError_VIRTUAL_DRIVE_UPSTREAM_ERROR_CREDENTIALS_NOT_FOUND VirtualDriveUpstreamError = 1
	// The credentials secret exists but could not be parsed into usable credentials (malformed JSON, or missing
	// accessKeyId/secretAccessKey). Admin fix: correct the secret's contents.
	VirtualDriveUpstreamError_VIRTUAL_DRIVE_UPSTREAM_ERROR_CREDENTIALS_INVALID VirtualDriveUpstreamError = 2
	// The provider rejected the (well-formed) credentials at read time (401/403): wrong/expired keys, or the
	// keys lack permission on the bucket. Admin fix: rotate the keys or grant access. FAILED_PRECONDITION rather
	// than PERMISSION_DENIED because it's the drive's stored credentials that are rejected, not the caller.
	VirtualDriveUpstreamError_VIRTUAL_DRIVE_UPSTREAM_ERROR_CREDENTIALS_REJECTED VirtualDriveUpstreamError = 3
	// The upstream provider service is unreachable or failing (network, outage, throttling). Transient
	// and possibly retryable — distinct from UPSTREAM_FILE_NOT_FOUND, where the provider is reachable
	// but no longer has the referenced file.
	VirtualDriveUpstreamError_VIRTUAL_DRIVE_UPSTREAM_ERROR_UPSTREAM_UNAVAILABLE VirtualDriveUpstreamError = 4
	// The upstream provider is reachable but no longer has the referenced file/version at the pinned
	// fingerprint (deleted, the version expired, or moved). Permanent for this revision, unlike the
	// transient UPSTREAM_UNAVAILABLE.
	VirtualDriveUpstreamError_VIRTUAL_DRIVE_UPSTREAM_ERROR_UPSTREAM_FILE_NOT_FOUND VirtualDriveUpstreamError = 5
	// The upstream provider is reachable but in a state that prevents the operation — e.g. a virtual drive
	// whose configured bucket no longer exists. Distinct from UPSTREAM_UNAVAILABLE (transient) and the
	// credentials errors (the credentials may be valid): an admin must repair the drive's configuration or
	// its backing store. FAILED_PRECONDITION rather than INVALID_ARGUMENT because the caller's request is
	// well-formed; it is the drive's upstream that is unusable.
	VirtualDriveUpstreamError_VIRTUAL_DRIVE_UPSTREAM_ERROR_INVALID_UPSTREAM_STATE VirtualDriveUpstreamError = 6
)

